function aggregateParams(){const f=applied.value;return {start_date:f.start_date,end_date:f.end_date,user_id:f.user_id,api_key_id:f.api_key_id,account_id:f.account_id,group_id:f.group_id,model:f.model,request_type:f.request_type,stream:f.request_type==='sync'?false:f.request_type==='stream'?true:f.stream,native_compaction_v2:f.native_compaction_v2,billing_type:f.billing_type};}
