async function loadTrend(){const rev=++trendVersion;trendLoading.value=true;trendError.value='';trend.value=[];try{const data=await getSnapshotV2({...aggregateParams(),granularity:granularity.value,include_stats:false,include_trend:true,include_model_stats:false,include_group_stats:false,include_users_trend:false});if(disposed||rev!==trendVersion)return;if(!data||typeof data!=='object'||Array.isArray(data)||('trend' in data&&(!Array.isArray(data.trend)||!data.trend.every(r=>typeof r?.date==='string'&&finiteFields(r,['input_tokens','output_tokens','cache_creation_tokens','cache_read_tokens','total_tokens'])))))throw new Error('趋势响应不完整，请重试');trend.value=data.trend ?? [];}catch(e){if(!disposed&&rev===trendVersion)trendError.value=text(e);}finally{if(rev===trendVersion)trendLoading.value=false;}}
