function openBreakdown(item:GroupStat|EndpointStat){const params=aggregateParams();if('group_id' in item){const {model,...rest}=params;breakdownParams={...rest,group_id:item.group_id,limit:50};breakdownTitle.value=`分组 ${item.group_name} · 用户分布`;}else{breakdownParams={...params,endpoint:item.endpoint,endpoint_type:endpointSource.value==='endpoints'?'inbound':endpointSource.value==='upstream_endpoints'?'upstream':'path',limit:50};breakdownTitle.value=`端点 ${item.endpoint} · 用户分布`;}void loadBreakdown();}
