const lineOptions={responsive:true,maintainAspectRatio:false,animation:false as const,plugins:{legend:{position:'bottom' as const,labels:{boxWidth:10,color:'#85858f'}}},scales:{x:{ticks:{color:'#85858f',maxTicksLimit:6},grid:{display:false}},y:{beginAtZero:true,ticks:{color:'#85858f'},grid:{color:'rgba(128,128,140,.12)'}}}};
